        self.documents = {}
        self.archived_documents = {}

    def is_valid_id(self, doc_id):
        return isinstance(doc_id, str) and '/' not in doc_id and '..' not in doc_id

    def create(self, doc_id, body):
        if not self.is_valid_id(doc_id):
            return 400
        if doc_id in self.documents or doc_id in self.archived_documents:
            return 409
        self.documents[doc_id] = body
        return 201

    def read(self, doc_id):
        if not self.is_valid_id(doc_id):
            return 400
        if doc_id in self.documents:
            return 200, self.documents[doc_id]
        if doc_id in self.archived_documents:
            return 200, self.archived_documents[doc_id]
        return 404, None

    def put(self, doc_id, body):
        if not self.is_valid_id(doc_id):
            return 400
        if doc_id not in self.documents and doc_id not in self.archived_documents:
            return 404
        if doc_id in self.archived_documents:
            return 409
        self.documents[doc_id] = body
        return 200

    def archive(self, doc_id):
        if not self.is_valid_id(doc_id):
            return 400
        if doc_id not in self.documents:
